import { Component, Prop, Vue } from 'vue-property-decorator';
import MenuArrow from '../../common/menu-arrow/index.vue';

@Component({
    name: 'SettingsMenuAccordion',
    components: {
        MenuArrow
    }
})
export default class SettingsMenuAccordion extends Vue {
    @Prop({
        type: String,
        required: true
    })
    public label: string;

    public isContentExpanded: boolean = false;

    public onExpandContent() {
        this.isContentExpanded = !this.isContentExpanded;
    }
}
